import { z } from 'zod';

export const Category = z.enum(['news', 'market', 'disaster']);
export type Category = z.infer<typeof Category>;

export const Region = z.enum([
  'africa',
  'asia',
  'europe',
  'north-america',
  'south-america',
  'oceania',
]);
export type Region = z.infer<typeof Region>;

export const Severity = z.int().min(1).max(5);
export type Severity = z.infer<typeof Severity>;

export const DisasterType = z.enum(['earthquake', 'flood', 'storm', 'wildfire']);
export type DisasterType = z.infer<typeof DisasterType>;

export const Role = z.enum(['user', 'admin']);
export type Role = z.infer<typeof Role>;

export const DeliveryStatus = z.enum([
  'pending',
  'sending',
  'sent',
  'failed',
  'dead',
  'skipped',
]);
export type DeliveryStatus = z.infer<typeof DeliveryStatus>;

import { z } from 'zod';

export const LIMITS = {
  name: 100,
  email: 254,
  passwordMin: 10,
  passwordMax: 128,
  title: 200,
  summary: 2000,
  keyword: 50,
  keywords: 20,
  symbol: 12,
  symbols: 20,
  targetIds: 20,
  url: 2048,
  slackText: 10_000,
  listDefault: 50,
  listMax: 200,
} as const;

export const Name = z.string().trim().min(1).max(LIMITS.name);

export const ListQuery = z.object({
  limit: z.coerce
    .number()
    .int()
    .min(1)
    .max(LIMITS.listMax)
    .default(LIMITS.listDefault),
});
export type ListQuery = z.infer<typeof ListQuery>;

export const PatchEnabled = z.object({ enabled: z.boolean() });
export type PatchEnabled = z.infer<typeof PatchEnabled>;

import { z } from 'zod';
import { LIMITS } from './common';
import { Role } from './enums';

// Trim and lowercase before the format check, so ' A@B.com ' is valid.
const Email = z
  .string()
  .trim()
  .toLowerCase()
  .pipe(z.email().max(LIMITS.email));

export const RegisterInput = z.object({
  email: Email,
  password: z.string().min(LIMITS.passwordMin).max(LIMITS.passwordMax),
});
export type RegisterInput = z.infer<typeof RegisterInput>;

export const LoginInput = z.object({
  email: Email,
  password: z.string().min(1).max(LIMITS.passwordMax),
});
export type LoginInput = z.infer<typeof LoginInput>;

export interface UserDto {
  id: string;
  email: string;
  role: Role;
}

import { z } from 'zod';
import { LIMITS } from './common';
import { Category, DisasterType, Region, Severity } from './enums';

export const TickerSymbol = z.string().trim().min(1).max(LIMITS.symbol);

export const NewsEventData = z.object({});
export type NewsEventData = z.infer<typeof NewsEventData>;

export const MarketEventData = z.object({
  symbol: TickerSymbol,
  price: z.number(),
  changePct: z.number(),
});
export type MarketEventData = z.infer<typeof MarketEventData>;

export const DisasterEventData = z.object({
  type: DisasterType,
  region: Region,
  magnitude: z.number().optional(),
});
export type DisasterEventData = z.infer<typeof DisasterEventData>;

const eventBase = {
  title: z.string().trim().min(1).max(LIMITS.title),
  summary: z.string().trim().max(LIMITS.summary).default(''),
  severity: Severity,
  occurredAt: z.iso.datetime({ offset: true }).optional(),
};

export const EventInput = z.discriminatedUnion('category', [
  z.object({ ...eventBase, category: z.literal('news'), data: NewsEventData }),
  z.object({
    ...eventBase,
    category: z.literal('market'),
    data: MarketEventData,
  }),
  z.object({
    ...eventBase,
    category: z.literal('disaster'),
    data: DisasterEventData,
  }),
]);
export type EventInput = z.infer<typeof EventInput>;

interface EventDataByCategory {
  news: NewsEventData;
  market: MarketEventData;
  disaster: DisasterEventData;
}

export type EventDto = {
  [K in Category]: { category: K; data: EventDataByCategory[K] };
}[Category] & {
  id: string;
  sourceId: string;
  title: string;
  summary: string;
  severity: Severity;
  occurredAt: string;
  createdAt: string;
};

export interface DevEventResult {
  event: EventDto;
  deliveriesCreated: number;
}

import { z } from 'zod';
import { LIMITS, Name } from './common';
import { DisasterType, Region, Severity } from './enums';
import { TickerSymbol } from './events';

export const NewsFilters = z.object({
  keywords: z
    .array(z.string().trim().min(1).max(LIMITS.keyword))
    .max(LIMITS.keywords),
});
export type NewsFilters = z.infer<typeof NewsFilters>;

export const MarketDirection = z.enum(['up', 'down', 'any']);
export type MarketDirection = z.infer<typeof MarketDirection>;

export const MarketFilters = z.object({
  symbols: z.array(TickerSymbol).max(LIMITS.symbols),
  direction: MarketDirection,
  minChangePct: z.number().min(0),
});
export type MarketFilters = z.infer<typeof MarketFilters>;

export const DisasterFilters = z.object({
  types: z.array(DisasterType).max(DisasterType.options.length),
  regions: z.array(Region).max(Region.options.length),
  minMagnitude: z.number().optional(),
});
export type DisasterFilters = z.infer<typeof DisasterFilters>;

const alertBase = {
  name: Name,
  minSeverity: Severity,
  targetIds: z
    .array(z.uuid())
    .min(1)
    .max(LIMITS.targetIds)
    .refine((ids) => new Set(ids).size === ids.length, {
      message: 'targetIds must be unique',
    }),
  enabled: z.boolean().default(true),
};

export const AlertInput = z.discriminatedUnion('category', [
  z.object({ ...alertBase, category: z.literal('news'), filters: NewsFilters }),
  z.object({
    ...alertBase,
    category: z.literal('market'),
    filters: MarketFilters,
  }),
  z.object({
    ...alertBase,
    category: z.literal('disaster'),
    filters: DisasterFilters,
  }),
]);
export type AlertInput = z.infer<typeof AlertInput>;

export type AlertDto = AlertInput & {
  id: string;
  createdAt: string;
  updatedAt: string;
};

import { z } from 'zod';
import { LIMITS, Name } from './common';

export const EmailConfig = z.object({
  address: z.string().trim().pipe(z.email().max(LIMITS.email)),
});
export type EmailConfig = z.infer<typeof EmailConfig>;

// Only the URL shape. The API checks SLACK_WEBHOOK_ALLOWED_PREFIXES.
export const SlackConfig = z.object({
  webhookUrl: z.url({ protocol: /^https?$/ }).max(LIMITS.url),
});
export type SlackConfig = z.infer<typeof SlackConfig>;

export interface ChannelField {
  key: string;
  label: string;
  inputType: 'text' | 'email' | 'url';
}

export interface ChannelDefinition {
  configSchema: z.ZodObject;
  label: string;
  fields: readonly ChannelField[];
}

export const channels = {
  email: {
    configSchema: EmailConfig,
    label: 'Email',
    fields: [{ key: 'address', label: 'Email address', inputType: 'email' }],
  },
  slack: {
    configSchema: SlackConfig,
    label: 'Slack',
    fields: [{ key: 'webhookUrl', label: 'Webhook URL', inputType: 'url' }],
  },
} satisfies Record<string, ChannelDefinition>;

export type ChannelId = keyof typeof channels;
const channelIds = Object.keys(channels) as [ChannelId, ...ChannelId[]];
export const ChannelId = z.enum(channelIds);

type TargetBranch<K extends ChannelId> = z.ZodObject<{
  name: typeof Name;
  channel: z.ZodLiteral<K>;
  config: (typeof channels)[K]['configSchema'];
}>;
type AnyTargetBranch = { [K in ChannelId]: TargetBranch<K> }[ChannelId];

// The cast restores the per-channel pairing that Array.map loses.
const targetBranches = channelIds.map((id) =>
  z.object({
    name: Name,
    channel: z.literal(id),
    config: channels[id].configSchema,
  }),
) as [AnyTargetBranch, ...AnyTargetBranch[]];

export const TargetInput = z.discriminatedUnion('channel', targetBranches);
export type TargetInput = z.infer<typeof TargetInput>;

export type TargetDto = TargetInput & { id: string; createdAt: string };

export type TargetTestResult = { ok: true } | { ok: false; error: string };

import { z } from 'zod';
import { LIMITS, ListQuery } from './common';
import { ChannelId } from './channels';
import { Category, DeliveryStatus } from './enums';
import { UserDto } from './auth';

export const AdminAlertsQuery = z.object({ userId: z.uuid() });
export type AdminAlertsQuery = z.infer<typeof AdminAlertsQuery>;

export const AdminEventsQuery = ListQuery.extend({
  category: Category.optional(),
});
export type AdminEventsQuery = z.infer<typeof AdminEventsQuery>;

export const AdminDeliveriesQuery = ListQuery.extend({
  status: DeliveryStatus.optional(),
  channel: ChannelId.optional(),
});
export type AdminDeliveriesQuery = z.infer<typeof AdminDeliveriesQuery>;

export type AdminUserDto = UserDto & { createdAt: string; alertCount: number };

export interface DeliveryDto {
  id: string;
  alertId: string;
  eventId: string;
  targetId: string;
  channel: ChannelId;
  status: DeliveryStatus;
  attempts: number;
  nextAttemptAt: string;
  lastError: string | null;
  sentAt: string | null;
  createdAt: string;
  updatedAt: string;
  eventTitle: string;
  alertName: string;
  targetName: string;
  userEmail: string;
}

export interface SourceDto {
  id: string;
  category: Category;
  enabled: boolean;
  updatedAt: string;
}

export interface ChannelDto {
  id: ChannelId;
  enabled: boolean;
  updatedAt: string;
}

export interface MetricsDto {
  since: string;
  eventsByCategory: Record<Category, number>;
  deliveriesByStatus: Record<DeliveryStatus, number>;
  failureRateByChannel: Record<ChannelId, number>;
}

export const MockSlackMessage = z.object({
  text: z.string().max(LIMITS.slackText),
});
export type MockSlackMessage = z.infer<typeof MockSlackMessage>;

export const MockSlackMode = z.object({ fail: z.boolean() });
export type MockSlackMode = z.infer<typeof MockSlackMode>;

import { z } from 'zod';
import { LIMITS } from './common';
import { EventDto } from './events';

export interface DevEventResult {
  event: EventDto;
  deliveriesCreated: number;
}

export const MockSlackMessage = z.object({
  text: z.string().max(LIMITS.slackText),
});
export type MockSlackMessage = z.infer<typeof MockSlackMessage>;

export const MockSlackMode = z.object({ fail: z.boolean() });
export type MockSlackMode = z.infer<typeof MockSlackMode>;

