import { TargetInput } from './channels';

const slackConfig = { webhookUrl: 'https://hooks.slack.com/services/T0/B0/x' };

describe('TargetInput', () => {
  it('accepts a slack config under channel slack', () => {
    const result = TargetInput.safeParse({
      name: 'Team',
      channel: 'slack',
      config: slackConfig,
    });
    expect(result.success).toBe(true);
  });

  it('rejects a slack config under channel email', () => {
    const result = TargetInput.safeParse({
      name: 'Team',
      channel: 'email',
      config: slackConfig,
    });
    expect(result.success).toBe(false);
  });
});

import { Severity } from './enums';

describe('Severity', () => {
  it.each([1, 5])('accepts %s', (value) => {
    expect(Severity.safeParse(value).success).toBe(true);
  });

  it.each([0, 6, 2.5])('rejects %s', (value) => {
    expect(Severity.safeParse(value).success).toBe(false);
  });
});

import { RegisterInput } from './auth';

describe('RegisterInput', () => {
  it('accepts a 10-character password', () => {
    const result = RegisterInput.safeParse({
      email: 'a@example.com',
      password: '0123456789',
    });
    expect(result.success).toBe(true);
  });

  it('rejects a 9-character password', () => {
    const result = RegisterInput.safeParse({
      email: 'a@example.com',
      password: '012345678',
    });
    expect(result.success).toBe(false);
  });

  it('trims and lowercases the email', () => {
    const result = RegisterInput.parse({
      email: '  Alice@Example.COM ',
      password: '0123456789',
    });
    expect(result.email).toBe('alice@example.com');
  });
});

import { ListQuery } from './common';

describe('ListQuery', () => {
  it('defaults a missing limit to 50', () => {
    expect(ListQuery.parse({}).limit).toBe(50);
  });

  it('coerces a limit from a query string', () => {
    expect(ListQuery.parse({ limit: '20' }).limit).toBe(20);
  });

  it('rejects a limit of 500', () => {
    expect(ListQuery.safeParse({ limit: '500' }).success).toBe(false);
  });
});

