node --input-type=module -e '
import {execFile} from "node:child_process";
import {promisify} from "node:util";
import {readFileSync} from "node:fs";
const run = promisify(execFile);
const json = path => JSON.parse(readFileSync(path,"utf8"));
const root = json("package.json");
const lock = json("package-lock.json");
const declared = Object.assign({}, root.dependencies, root.devDependencies, json("apps/api/package.json").dependencies, json("libs/shared/package.json").dependencies);
const named = /^(cn|class-variance-authority|fastify(?:-plugin)?|@fastify\/|@spartan-ng\/|@angular\/(build|cdk|core)$|@types\/node|nx$|@nx\/(angular|node|vitest)$)/;
const tasks = Object.entries(declared).map(([name, range]) => ({name, range, spec: `${name}@${lock.packages[`node_modules/${name}`]?.version ?? range}`}));
tasks.push(...["@nx/angular","@nx/node","@nx/vitest"].map(name=>({name,range:true,spec:`${name}@${declared[name]}`})), {name:"npm",spec:`npm@${root.packageManager.split("@")[1]}`});
const results = await Promise.all(tasks.map(({name,range,spec}) => async ()=>{try {const fields=range===true ? ["version"] : ["version","engines",...(named.test(name)?["description","peerDependencies"]:[])]; const {stdout}=await run("npm",["view",spec,...fields,"--json","--fetch-retries=0","--fetch-timeout=10000","--logs-max=0"]); const result=JSON.parse(stdout); if(range===true) return `${spec} candidates ${JSON.stringify(result)}`; return named.test(name) ? `${spec} ${JSON.stringify(result)}` : `${spec} ${JSON.stringify(result.engines??{})}`; } catch(error){return `${spec} FAILED ${error.message.split("\n").slice(-4).join(" ")}`;}}).reduce((lanes, task, index)=>{lanes[index % lanes.length].push(task);return lanes;}, Array.from({length:12},()=>[])).map(async lane=>{const out=[];for(const task of lane)out.push(await task());return out;}));
console.log(results.flat().sort().join("\n"));
'

