const { EventInput } = require("./libs/shared/src/lib/events.ts");
const { AlertInput } = require("./libs/shared/src/lib/alerts.ts");
const { ListQuery } = require("./libs/shared/src/lib/common.ts");
const { SlackConfig } = require("./libs/shared/src/lib/channels.ts");
const event = { title:"River floods town", severity:3 };
const id = "3f2b8c1e-9d4a-4f6b-8a2e-1c5d7e9f0a3b";
const alert = { name:"Example", minSeverity:3, targetIds:[id] };
const checks = [
["news accepts disaster data", EventInput, {...event, category:"news", data:{type:"flood", region:"europe"}}],
["market accepts nested category", EventInput, {...event, category:"market", data:{symbol:"AAPL",price:125,changePct:-2,category:"news"}}],
["news accepts nested category and mixed filters", AlertInput, {...alert, category:"news", filters:{keywords:[],category:"market",symbols:["AAPL"],direction:"up",minChangePct:2}}],
["alert with duplicate UUID", AlertInput, {...alert, category:"news", targetIds:[id,id],filters:{keywords:[]}}],
["list limit 200", ListQuery,{limit:"200"}],
["Slack dev URL", SlackConfig,{webhookUrl:"http://localhost:3000/api/dev/mock-slack/local"}]
];
for(const [label,schema,input] of checks){const result=schema.safeParse(input); console.log(label, result.success, result.success ? JSON.stringify(result.data) : result.error.issues.map(issue=>issue.message).join("; "));}
'

