const assert=require("node:assert/strict");
const {readFileSync}=require("node:fs");
const {resolve}=require("node:path");
const {createRequire}=require("node:module");
const ts=require("typescript");
const folder=resolve("libs/shared/src/lib");
function load(file, replace, dependencies={}) {
 const path=resolve(folder,file+".ts");
 const requireLocal=createRequire(path);
 const input=readFileSync(path,"utf8");
 const source=replace ? replace(input) : input;
 assert.ok(!replace || source!==input, `No mutation applied to ${file}`);
 const {outputText}=ts.transpileModule(source,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.CommonJS}});
 const module={exports:{}};
 new Function("module","exports","require",outputText)(module,module.exports,name=>Object.hasOwn(dependencies,name) ? dependencies[name] : requireLocal(name));
 return module.exports;
}
function tests(file, dependencies={}) {
 const results=new Map();
 global.describe=(_name, callback)=>callback();
 global.it=(name,callback)=>{try{callback();results.set(name,"pass");}catch{results.set(name,"fail");}};
 global.it.each=values=>(name,callback)=>values.forEach((value)=>it(name.replace("%s",value).replace("$category",value?.category),()=>callback(value)));
 global.expect=actual=>({toBe:expected=>assert.strictEqual(actual,expected)});
 load(file+".spec",undefined,dependencies);
 return results;
}
for(const file of ["alerts","events","channels","auth","enums","common"]) {
 const base=tests(file);assert.ok([...base.values()].every(result=>result==="pass"));console.log(`${file}: ${base.size} original assertions passed`);
}
const mutate = [
 ["alerts","detach filters from category",source=>source.replace(/filters: (News|Market|Disaster)Filters/g,"filters: z.union([NewsFilters, MarketFilters, DisasterFilters])")],
 ["events","detach data from category",source=>source.replace(/data: (News|Market|Disaster)EventData/g,"data: z.union([NewsEventData, MarketEventData, DisasterEventData])")],
 ["channels","detach config from channel",source=>source.replace("config: channels[id].configSchema","config: z.union([EmailConfig, SlackConfig])")],
 ["enums","remove minimum",source=>source.replace(".min(1)","")],
 ["enums","remove maximum",source=>source.replace(".max(5)","")],
 ["enums","allow fractions",source=>source.replace("z.int()","z.number()")],
 ["auth","remove password minimum",source=>source.replace(".min(LIMITS.passwordMin)","")],
 ["auth","remove lowercase",source=>source.replace(".toLowerCase()","")],
 ["auth","remove trim",source=>source.replace(".trim()","")],
 ["common","remove limit default",source=>source.replace(".default(LIMITS.listDefault)","")],
 ["common","remove limit maximum",source=>source.replace(".max(LIMITS.listMax)","")],
 ["common","remove limit coercion",source=>source.replace("z.coerce","z")],
];
for(const [file,label,replacement] of mutate){const caught=[...tests(file,{[`./${file}`]:load(file,replacement)})].filter(([,result])=>result==="fail").map(([name])=>name);console.log(`${label}: ${caught.join(", ") || "SURVIVED"}`);assert.ok(caught.length);}
const Fastify=require("fastify");
const {app}=require("./apps/api/src/app/app.ts");
(async()=>{const server=Fastify();try{server.register(app);const health=await server.inject("/api/health");assert.equal(health.statusCode,200);assert.deepEqual(health.json(),{status:"ok"});assert.equal((await server.inject("/")).statusCode,404);console.log("GET /api/health and absent scaffold root passed injection");}finally{await server.close();}})().catch(error=>{console.error(error);process.exitCode=1;});
'

