import type { ZodType } from 'zod';
import type { ChannelId } from '@alerts/shared';

export interface NotificationMessage {
  subject: string;
  text: string;
}

export interface NotificationChannel<C> {
  readonly id: ChannelId;
  readonly configSchema: ZodType<C>;
  // Extra server-side checks, such as the Slack URL allowlist. Throws on invalid config.
  assertConfigAllowed?(config: C): void;
  // Throws on failure with a message that contains no secrets. The worker stores it in last_error.
  send(config: C, message: NotificationMessage): Promise<void>;
}

// Messages never contain the URL, because a webhook URL is a secret.
export class SlackUrlError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SlackUrlError';
  }
}

export function assertAllowedSlackUrl(
  raw: string,
  prefixes: readonly string[],
): URL {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    throw new SlackUrlError('Webhook URL is not a valid URL');
  }
  if (url.username !== '' || url.password !== '') {
    throw new SlackUrlError('Webhook URL must not contain a username or password');
  }
  // The parsed origin and path are normalized, so tricks such as "/../" or a query are already resolved.
  const location = url.origin + url.pathname;
  if (!prefixes.some((prefix) => location.startsWith(prefix))) {
    throw new SlackUrlError('Webhook URL is not on the allowed list');
  }
  return url;
}

import { SlackConfig } from '@alerts/shared';
import type { NotificationChannel } from './channel';
import { assertAllowedSlackUrl } from './slack-url';

const DEFAULT_TIMEOUT_MS = 5000;

export interface SlackChannelOptions {
  timeoutMs?: number;
}

// Slack reads <...> as links and mentions such as <!channel>, so event text must not create them.
function escapeSlack(text: string): string {
  return text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

export function createSlackChannel(
  allowedPrefixes: readonly string[],
  options: SlackChannelOptions = {},
): NotificationChannel<SlackConfig> {
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  return {
    id: 'slack',
    configSchema: SlackConfig,
    assertConfigAllowed(config) {
      assertAllowedSlackUrl(config.webhookUrl, allowedPrefixes);
    },
    async send(config, message) {
      const url = assertAllowedSlackUrl(config.webhookUrl, allowedPrefixes);
      const text = `*${escapeSlack(message.subject)}*\n${escapeSlack(message.text)}`;
      const signal = AbortSignal.timeout(timeoutMs);
      let status: number;
      try {
        const response = await fetch(url.href, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ text }),
          redirect: 'error',
          signal,
        });
        status = response.status;
        await response.body?.cancel();
      } catch {
        // The fetch error and its cause can hold the URL, so neither is passed on.
        throw new Error(
          signal.aborted ? 'Slack request timed out' : 'Slack request failed',
        );
      }
      if (status < 200 || status > 299) {
        throw new Error(`Slack responded ${status}`);
      }
    },
  };
}

import { createTransport } from 'nodemailer';
import { EmailConfig } from '@alerts/shared';
import type { Config } from '../config';
import type { NotificationChannel } from './channel';

// The Nodemailer defaults run up to 10 minutes, longer than the delivery lease.
const SMTP_TIMEOUT_MS = 10_000;

function smtpErrorMessage(error: unknown): string {
  const code =
    error instanceof Error && 'code' in error && typeof error.code === 'string'
      ? error.code
      : undefined;
  return code ? `SMTP error: ${code}` : 'SMTP error';
}

export function createEmailChannel(
  config: Pick<Config, 'SMTP_HOST' | 'SMTP_PORT' | 'MAIL_FROM'>,
): NotificationChannel<EmailConfig> {
  const transport = createTransport({
    host: config.SMTP_HOST,
    port: config.SMTP_PORT,
    secure: false,
    connectionTimeout: SMTP_TIMEOUT_MS,
    greetingTimeout: SMTP_TIMEOUT_MS,
    socketTimeout: SMTP_TIMEOUT_MS,
  });
  return {
    id: 'email',
    configSchema: EmailConfig,
    async send(target, message) {
      try {
        await transport.sendMail({
          from: config.MAIL_FROM,
          to: target.address,
          subject: message.subject,
          text: message.text,
        });
      } catch (error) {
        // Nodemailer messages can quote the server reply or credentials, so only the code is kept.
        throw new Error(smtpErrorMessage(error));
      }
    },
  };
}

import type { z } from 'zod';
import type { ChannelId, channels } from '@alerts/shared';
import type { Config } from '../config';
import type { NotificationChannel, NotificationMessage } from './channel';
import { createEmailChannel } from './email';
import { createSlackChannel } from './slack';

type ChannelConfig<K extends ChannelId> = z.infer<
  (typeof channels)[K]['configSchema']
>;

// Keyed by every shared ChannelId, so a channel without an implementation fails to compile.
export type ChannelRegistry = {
  readonly [K in ChannelId]: NotificationChannel<ChannelConfig<K>>;
};

export function createChannelRegistry(config: Config): ChannelRegistry {
  return {
    email: createEmailChannel(config),
    slack: createSlackChannel(config.SLACK_WEBHOOK_ALLOWED_PREFIXES),
  };
}

// The compiler cannot pair a channel id with its config type, so callers get the channel with config unknown.
export function channelById(
  registry: ChannelRegistry,
  id: ChannelId,
): NotificationChannel<unknown> {
  return registry[id];
}

// Stored config is parsed with the channel's own schema before it reaches send.
export async function sendThroughChannel(
  registry: ChannelRegistry,
  target: { channel: ChannelId; config: unknown },
  message: NotificationMessage,
): Promise<void> {
  const channel = channelById(registry, target.channel);
  const parsed = channel.configSchema.safeParse(target.config);
  if (!parsed.success) {
    throw new Error('Stored target config is invalid');
  }
  await channel.send(parsed.data, message);
}

import type { Category, ChannelId } from '@alerts/shared';
import type { Db } from './client';
import { channels, sources } from './schema';

export interface RegistryRows {
  channelIds: readonly ChannelId[];
  sources: readonly { id: string; category: Category }[];
}

// "On conflict do nothing" keeps every switch the admin has already set.
export async function syncRegistryRows(
  db: Db,
  registry: RegistryRows,
): Promise<void> {
  if (registry.channelIds.length > 0) {
    await db
      .insert(channels)
      .values(registry.channelIds.map((id) => ({ id, enabled: true })))
      .onConflictDoNothing();
  }
  if (registry.sources.length > 0) {
    await db
      .insert(sources)
      .values(
        registry.sources.map(({ id, category }) => ({
          id,
          category,
          enabled: true,
        })),
      )
      .onConflictDoNothing();
  }
}

import type { EventDto, Region } from '@alerts/shared';
import type { NotificationMessage } from '../channels/channel';

type PickEach<T, K extends keyof T> = T extends unknown ? Pick<T, K> : never;

// One branch per category, so data stays paired with its category.
export type MessageEvent = PickEach<
  EventDto,
  'category' | 'title' | 'summary' | 'severity' | 'data'
>;

const numberFormat = new Intl.NumberFormat('en-US', {
  maximumFractionDigits: 2,
});

function capitalize(word: string): string {
  return word.charAt(0).toUpperCase() + word.slice(1);
}

function regionName(region: Region): string {
  return region.split('-').map(capitalize).join(' ');
}

function describeData(event: MessageEvent): string | undefined {
  switch (event.category) {
    case 'news':
      return undefined;
    case 'market': {
      const { symbol, price, changePct } = event.data;
      const price2 = numberFormat.format(price);
      if (changePct === 0) {
        return `${symbol} is unchanged at ${price2}.`;
      }
      const verb = changePct > 0 ? 'rose' : 'fell';
      return `${symbol} ${verb} ${numberFormat.format(Math.abs(changePct))}% to ${price2}.`;
    }
    case 'disaster': {
      const { type, region, magnitude } = event.data;
      const size =
        magnitude === undefined
          ? ''
          : `, magnitude ${numberFormat.format(magnitude)}`;
      return `${capitalize(type)} in ${regionName(region)}${size}.`;
    }
  }
}

export function buildMessage(
  event: MessageEvent,
  alertName: string,
): NotificationMessage {
  const lines = [
    event.summary,
    `Severity: ${event.severity} of 5`,
    describeData(event),
    `Alert: ${alertName}`,
  ].filter((line): line is string => line !== undefined && line !== '');
  return {
    subject: `[${event.category}] ${event.title}`,
    text: lines.join('\n'),
  };
}

export function buildTestMessage(targetName: string): NotificationMessage {
  return {
    subject: 'Test message',
    text: `This is a test message for the target "${targetName}". If you can read it, the target works.`,
  };
}

