import type {
  AlertInput,
  DisasterEventData,
  DisasterFilters,
  EventDto,
  MarketEventData,
  MarketFilters,
  NewsFilters,
} from '@alerts/shared';

type PickEach<T, K extends keyof T> = T extends unknown ? Pick<T, K> : never;

// One branch per category, so data and filters stay paired with their category.
export type MatchEvent = PickEach<
  EventDto,
  'category' | 'title' | 'summary' | 'severity' | 'data'
>;
export type MatchAlert = PickEach<
  AlertInput,
  'category' | 'minSeverity' | 'filters'
>;

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// \b only knows ASCII word characters, so it fails for keywords such as C++, $TSLA or café.
function keywordPattern(keyword: string): RegExp {
  return new RegExp(
    String.raw`(?<![\p{L}\p{N}])${escapeRegExp(keyword)}(?![\p{L}\p{N}])`,
    'iu',
  );
}

function matchesNews(
  event: { title: string; summary: string },
  filters: NewsFilters,
): boolean {
  if (filters.keywords.length === 0) {
    return true;
  }
  return filters.keywords.some((keyword) => {
    const pattern = keywordPattern(keyword);
    return pattern.test(event.title) || pattern.test(event.summary);
  });
}

function matchesMarket(data: MarketEventData, filters: MarketFilters): boolean {
  const symbol = data.symbol.toUpperCase();
  const symbolMatches =
    filters.symbols.length === 0 ||
    filters.symbols.some((candidate) => candidate.toUpperCase() === symbol);
  const directionMatches =
    filters.direction === 'any' ||
    (filters.direction === 'up' && data.changePct > 0) ||
    (filters.direction === 'down' && data.changePct < 0);
  return (
    symbolMatches &&
    directionMatches &&
    Math.abs(data.changePct) >= filters.minChangePct
  );
}

function matchesDisaster(
  data: DisasterEventData,
  filters: DisasterFilters,
): boolean {
  if (filters.types.length > 0 && !filters.types.includes(data.type)) {
    return false;
  }
  if (filters.regions.length > 0 && !filters.regions.includes(data.region)) {
    return false;
  }
  if (filters.minMagnitude !== undefined && data.type === 'earthquake') {
    return (
      data.magnitude !== undefined && data.magnitude >= filters.minMagnitude
    );
  }
  return true;
}

export function matchesFilters(event: MatchEvent, alert: MatchAlert): boolean {
  if (event.severity < alert.minSeverity) {
    return false;
  }
  if (event.category === 'news' && alert.category === 'news') {
    return matchesNews(event, alert.filters);
  }
  if (event.category === 'market' && alert.category === 'market') {
    return matchesMarket(event.data, alert.filters);
  }
  if (event.category === 'disaster' && alert.category === 'disaster') {
    return matchesDisaster(event.data, alert.filters);
  }
  return false;
}

import type { Severity } from '@alerts/shared';

// Each threshold the value reaches adds one level, starting from 1.
function severityFrom(value: number, thresholds: readonly number[]): Severity {
  return 1 + thresholds.filter((threshold) => value >= threshold).length;
}

export function marketSeverity(changePct: number): Severity {
  return severityFrom(Math.abs(changePct), [2, 5, 10, 20]);
}

export function earthquakeSeverity(magnitude: number): Severity {
  return severityFrom(magnitude, [5, 6, 7, 8]);
}

import { and, desc, eq, inArray } from 'drizzle-orm';
import type { FastifyInstance } from 'fastify';
import {
  AlertInput,
  IdParam,
  PatchEnabled,
  type AlertDto,
} from '@alerts/shared';
import { currentUser, requireUser } from '../auth/guards';
import type { Db } from '../db/client';
import { alerts, alertTargets, targets } from '../db/schema';
import { HttpError } from '../http-error';

type AlertRow = typeof alerts.$inferSelect;
type Tx = Parameters<Parameters<Db['transaction']>[0]>[0];

function toAlertDto(row: AlertRow, targetIds: string[]): AlertDto {
  // The routes validated category and filters together, which the column types cannot express.
  return {
    id: row.id,
    name: row.name,
    category: row.category,
    filters: row.filters,
    minSeverity: row.minSeverity,
    enabled: row.enabled,
    targetIds,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  } as AlertDto;
}

async function targetIdsByAlert(
  db: Db,
  alertIds: string[],
): Promise<Map<string, string[]>> {
  const byAlert = new Map(alertIds.map((id) => [id, [] as string[]]));
  if (alertIds.length === 0) {
    return byAlert;
  }
  const rows = await db
    .select()
    .from(alertTargets)
    .where(inArray(alertTargets.alertId, alertIds));
  for (const row of rows) {
    byAlert.get(row.alertId)?.push(row.targetId);
  }
  return byAlert;
}

async function assertOwnTargets(
  tx: Tx,
  userId: string,
  targetIds: string[],
): Promise<void> {
  // The lock makes a concurrent target delete either wait for this transaction or finish first and fail the check.
  const owned = await tx
    .select({ id: targets.id })
    .from(targets)
    .where(and(eq(targets.userId, userId), inArray(targets.id, targetIds)))
    .for('key share');
  // AlertInput rejects repeated ids, so the counts compare.
  if (owned.length !== targetIds.length) {
    throw new HttpError(400, 'targetIds: every target must be one of yours');
  }
}

async function linkTargets(
  tx: Tx,
  alertId: string,
  targetIds: string[],
): Promise<void> {
  await tx
    .insert(alertTargets)
    .values(targetIds.map((targetId) => ({ alertId, targetId })));
}

export async function alertRoutes(app: FastifyInstance): Promise<void> {
  app.addHook('preHandler', requireUser);

  app.get('/', async (request) => {
    const user = currentUser(request);
    const rows = await app.db
      .select()
      .from(alerts)
      .where(eq(alerts.userId, user.id))
      .orderBy(desc(alerts.createdAt));
    const targetIds = await targetIdsByAlert(
      app.db,
      rows.map((row) => row.id),
    );
    return rows.map((row) => toAlertDto(row, targetIds.get(row.id) ?? []));
  });

  app.post('/', async (request, reply) => {
    const user = currentUser(request);
    const { targetIds, ...fields } = AlertInput.parse(request.body);
    const row = await app.db.transaction(async (tx) => {
      await assertOwnTargets(tx, user.id, targetIds);
      const [alert] = await tx
        .insert(alerts)
        .values({ ...fields, userId: user.id })
        .returning();
      await linkTargets(tx, alert.id, targetIds);
      return alert;
    });
    reply.code(201);
    return toAlertDto(row, targetIds);
  });

  app.get('/:id', async (request) => {
    const user = currentUser(request);
    const { id } = IdParam.parse(request.params);
    const [row] = await app.db
      .select()
      .from(alerts)
      .where(and(eq(alerts.id, id), eq(alerts.userId, user.id)))
      .limit(1);
    if (!row) {
      throw new HttpError(404, 'Alert not found');
    }
    const targetIds = await targetIdsByAlert(app.db, [row.id]);
    return toAlertDto(row, targetIds.get(row.id) ?? []);
  });

  app.put('/:id', async (request) => {
    const user = currentUser(request);
    const { id } = IdParam.parse(request.params);
    const { targetIds, ...fields } = AlertInput.parse(request.body);
    const row = await app.db.transaction(async (tx) => {
      // The schema's $onUpdate sets updated_at.
      const [alert] = await tx
        .update(alerts)
        .set(fields)
        .where(and(eq(alerts.id, id), eq(alerts.userId, user.id)))
        .returning();
      if (!alert) {
        throw new HttpError(404, 'Alert not found');
      }
      await assertOwnTargets(tx, user.id, targetIds);
      await tx.delete(alertTargets).where(eq(alertTargets.alertId, id));
      await linkTargets(tx, id, targetIds);
      return alert;
    });
    return toAlertDto(row, targetIds);
  });

  app.patch('/:id', async (request) => {
    const user = currentUser(request);
    const { id } = IdParam.parse(request.params);
    const { enabled } = PatchEnabled.parse(request.body);
    const [row] = await app.db
      .update(alerts)
      .set({ enabled })
      .where(and(eq(alerts.id, id), eq(alerts.userId, user.id)))
      .returning();
    if (!row) {
      throw new HttpError(404, 'Alert not found');
    }
    const targetIds = await targetIdsByAlert(app.db, [row.id]);
    return toAlertDto(row, targetIds.get(row.id) ?? []);
  });

  app.delete('/:id', async (request, reply) => {
    const user = currentUser(request);
    const { id } = IdParam.parse(request.params);
    const deleted = await app.db
      .delete(alerts)
      .where(and(eq(alerts.id, id), eq(alerts.userId, user.id)))
      .returning({ id: alerts.id });
    if (deleted.length === 0) {
      throw new HttpError(404, 'Alert not found');
    }
    return reply.code(204).send();
  });
}

import { matchesFilters, type MatchAlert, type MatchEvent } from './match';

function newsEvent(title: string, summary = ''): MatchEvent {
  return { category: 'news', title, summary, severity: 3, data: {} };
}

function newsAlert(keywords: string[]): MatchAlert {
  return { category: 'news', minSeverity: 1, filters: { keywords } };
}

function marketEvent(symbol: string, changePct: number): MatchEvent {
  return {
    category: 'market',
    title: `${symbol} moves`,
    summary: '',
    severity: 3,
    data: { symbol, price: 100, changePct },
  };
}

function marketAlert(
  filters: Partial<Extract<MatchAlert, { category: 'market' }>['filters']>,
): MatchAlert {
  return {
    category: 'market',
    minSeverity: 1,
    filters: { symbols: [], direction: 'any', minChangePct: 0, ...filters },
  };
}

function disasterEvent(
  data: Extract<MatchEvent, { category: 'disaster' }>['data'],
): MatchEvent {
  return {
    category: 'disaster',
    title: 'Disaster',
    summary: '',
    severity: 3,
    data,
  };
}

function disasterAlert(
  filters: Partial<Extract<MatchAlert, { category: 'disaster' }>['filters']>,
): MatchAlert {
  return {
    category: 'disaster',
    minSeverity: 1,
    filters: { types: [], regions: [], ...filters },
  };
}

describe('matchesFilters', () => {
  describe('news', () => {
    it.each<[string, MatchEvent, string[], boolean]>([
      ['"oil" in "Oil prices"', newsEvent('Oil prices climb'), ['oil'], true],
      ['"oil" inside "boil"', newsEvent('Water starts to boil'), ['oil'], false],
      ['"oil" inside "oilfield"', newsEvent('New oilfield found'), ['oil'], false],
